// Mirrors indicators::ProgressDisplay. Field order matches the C++ layout
// (sizeof == 8, current at offset 0, total at offset 4).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ProgressDisplay {
    current: i32, // offset 0
    total: i32,   // offset 4
}

impl Default for ProgressDisplay {
    // C++ `ProgressDisplay displays[3];` must default-construct. Unobservable in
    // this program (all 3 slots are overwritten before any read; gcc dead-stored
    // the default ctor away entirely). Mirrors `ProgressDisplay(int total = 100)`.
    fn default() -> Self { Self { current: 0, total: 100 } }
}

impl ProgressDisplay {
    /// C++: explicit ProgressDisplay(int total)  -> current starts at 0.
    pub fn new(total: i32) -> Self { Self { current: 0, total } }

    /// C++: void update(int current)  -> plain assignment, NO clamping.
    pub fn update(&mut self, current: i32) { self.current = current; }

    /// C++: void increment(int amount) -> current += amount, total untouched.
    /// wrapping_add mirrors what gcc -O2 emits for signed int overflow.
    pub fn increment(&mut self, amount: i32) {
        self.current = self.current.wrapping_add(amount);
    }

    /// (current / total) * 100 evaluated ENTIRELY in f32 — division before the
    /// multiply. Do not "simplify" to current * 100 / total: results differ.
    fn percent(&self) -> f32 {
        (self.current as f32) / (self.total as f32) * 100.0f32
    }

    /// C++: std::string display() const
    /// oss << "Progress: " << std::fixed << std::setprecision(1) << pct
    ///     << "% (" << current << "/" << total << ")";
    /// No trailing newline (the caller's std::endl supplies it).
    pub fn display(&self) -> String {
        let p = self.percent() as f64; // cvtss2sd, then ostream _M_insert<double>
        // libstdc++/glibc "%.1f" prints inf/-inf/nan/-nan; Rust prints "inf"/"NaN",
        // so non-finite cases must be spelled out to stay byte-identical.
        let pct = if p.is_nan() {
            if p.is_sign_negative() { "-nan".to_string() } else { "nan".to_string() }
        } else if p.is_infinite() {
            if p < 0.0 { "-inf".to_string() } else { "inf".to_string() }
        } else {
            format!("{:.1}", p) // matches glibc %.1f incl. round-half-to-even ties
        };
        format!("Progress: {}% ({}/{})", pct, self.current, self.total)
    }
}

